const items = $input.all();

const analyses = items.map(item => {
  const props = item.json.properties || {};
  const nom = props['Nom'] && props['Nom'].title ? (props['Nom'].title[0] && props['Nom'].title[0].text ? props['Nom'].title[0].text.content : 'Sans titre') : 'Sans titre';
  const score = props['Score Global'] && props['Score Global'].number !== null ? props['Score Global'].number : 0;
  const axes = props['Axes Amelioration'] && props['Axes Amelioration'].rich_text ? props['Axes Amelioration'].rich_text.map(t => t.text ? t.text.content : '').join('') : '';
  const resume = props['Resume'] && props['Resume'].rich_text ? props['Resume'].rich_text.map(t => t.text ? t.text.content : '').join('') : '';
  const platform = props['Plateforme'] && props['Plateforme'].rich_text ? props['Plateforme'].rich_text.map(t => t.text ? t.text.content : '').join('') : '';
  return { nom, score, axes, resume, platform };
});

const analysesText = analyses.map(a =>
  'Post "' + a.nom + '" sur ' + a.platform + ' — Score: ' + a.score + '/10\n' +
  'Axes a ameliorer: ' + a.axes + '\n' +
  'Resume: ' + a.resume
).join('\n\n---\n\n');

return [{ json: { analysesText, nbAnalyses: analyses.length } }];

const veilleItems = $input.all();
const analysesData = $('Formater Analyses').first().json;

let veilleText = 'Aucune veille disponible.';
if (veilleItems.length > 0) {
  const v = veilleItems[0].json.properties || {};
  const angles = v['Angles Non Exploites'] && v['Angles Non Exploites'].rich_text ? v['Angles Non Exploites'].rich_text.map(t => t.text ? t.text.content : '').join('') : '';
  const themes = v['Themes Dominants'] && v['Themes Dominants'].rich_text ? v['Themes Dominants'].rich_text.map(t => t.text ? t.text.content : '').join('') : '';
  const motsCles = v['Mots Cles'] && v['Mots Cles'].rich_text ? v['Mots Cles'].rich_text.map(t => t.text ? t.text.content : '').join('') : '';
  const recos = v['Recommandations'] && v['Recommandations'].rich_text ? v['Recommandations'].rich_text.map(t => t.text ? t.text.content : '').join('') : '';
  const positAnna = v['Positionnement Anna'] && v['Positionnement Anna'].rich_text ? v['Positionnement Anna'].rich_text.map(t => t.text ? t.text.content : '').join('') : '';
  veilleText = 'Themes dominants concurrents: ' + themes + '\n' +
    'Angles non exploites: ' + angles + '\n' +
    'Mots-cles opportunites: ' + motsCles + '\n' +
    'Positionnement Anna vs concurrence: ' + positAnna + '\n' +
    'Recommandations: ' + recos;
}

const schema = '{"suggestions":[' +
  '{"titre":"...","plateforme":"YouTube","format":"Video courte","hook":"...","message_cle":"...","cta":"...","hashtags":["#h1","#h2","#h3"],"priorite":"Haute","probleme_cible":"Douleur principale adressee","solution":"Description de la solution proposee dans le post"},' +
  '{"titre":"...","plateforme":"TikTok","format":"Reel","hook":"...","message_cle":"...","cta":"...","hashtags":["#h1","#h2","#h3"],"priorite":"Haute","probleme_cible":"...","solution":"..."},' +
  '{"titre":"...","plateforme":"Facebook","format":"Post texte","hook":"...","message_cle":"...","cta":"...","hashtags":["#h1","#h2","#h3"],"priorite":"Moyenne","probleme_cible":"...","solution":"..."},' +
  '{"titre":"...","plateforme":"YouTube","format":"Video longue","hook":"...","message_cle":"...","cta":"...","hashtags":["#h1","#h2","#h3"],"priorite":"Moyenne","probleme_cible":"...","solution":"..."},' +
  '{"titre":"...","plateforme":"TikTok","format":"Carrousel","hook":"...","message_cle":"...","cta":"...","hashtags":["#h1","#h2","#h3"],"priorite":"Faible","probleme_cible":"...","solution":"..."}' +
  '],"conseil_global":"Recommandation strategique globale en 3 phrases"}';

const prompt = 'Tu es un expert en strategie de contenu pour Anna Ollivier, psychologue clinicienne qui publie sur YouTube, TikTok et Facebook. ' +
  'Elle vend une formation en ligne sur la gestion emotionnelle et la confiance en soi. Son persona : adultes 25-45 ans en quete d outils pratiques.\n\n' +
  '== ANALYSES DE SES CONTENUS RECENTS ==\n' + analysesData.analysesText + '\n\n' +
  '== DONNEES DE VEILLE CONCURRENTIELLE ==\n' + veilleText + '\n\n' +
  'Sur la base de ces donnees, genere 5 idees de posts optimisees pour Anna. ' +
  'Varie les plateformes (YouTube, TikTok, Facebook) et les formats (video courte, carrousel, post texte, reel, video longue). ' +
  'Chaque idee doit exploiter les angles non couverts par la concurrence et corriger les faiblesses identifiees.\n\n' +
  'Pour chaque suggestion, definis clairement le probleme cible du persona et la solution apportee par le post.\n\n' +
  'Reponds UNIQUEMENT avec un JSON valide, sans backtick ni commentaire :\n' + schema;

const apiBody = JSON.stringify({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 3000,
  messages: [{ role: 'user', content: prompt }]
});

return [{ json: { prompt, apiBody, dateGeneration: new Date().toISOString().split('T')[0] } }];

// Appel LLM — Ollama du VPS, reseau Docker interne.
// AUCUNE authentification, donc AUCUN secret dans ce noeud. C'est la raison du
// basculement depuis Anthropic, dont la cle etait ecrite en dur ici : un noeud
// Code N8N ne peut ni lire $env ni utiliser httpRequestWithAuthentication, donc
// appeler une API a cle depuis un Code node oblige a versionner le secret.
const OLLAMA_URL = 'http://172.18.0.1:11434/api/chat';
const MODELE = 'glm-5.2:cloud';
const NUM_PREDICT = 6000;

const prompt = $input.first().json.prompt;

let responseText = null;
let erreur = null;

try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: OLLAMA_URL,
    body: JSON.stringify({
      model: MODELE,
      messages: [{ role: 'user', content: prompt }],
      stream: false,
      // Obligatoire : sur un modele de raisonnement, le « thinking » consomme
      // tout num_predict et message.content revient vide.
      think: false,
      options: { num_predict: NUM_PREDICT }
    }),
    timeout: 300000
  });
  if (resp && resp.message && resp.message.content) {
    responseText = resp.message.content;
  } else {
    erreur = 'reponse sans message.content (think non desactive ?)';
  }
} catch (e) {
  erreur = e.message;
}

if (!responseText) {
  throw new Error('Appel LLM (' + MODELE + ') echoue : ' + (erreur || 'inconnue'));
}

// Sortie au format Anthropic : les noeuds Parse en aval restent inchanges.
return [{ json: {
  content: [{ type: 'text', text: responseText }],
  model: MODELE,
  type: 'message',
  role: 'assistant'
} }];

const claudeResponse = $json;
let claudeText = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  claudeText = claudeResponse.content[0].text || '';
} else {
  claudeText = JSON.stringify(claudeResponse);
}

let parsed = { suggestions: [], conseil_global: '' };
try {
  parsed = JSON.parse(claudeText);
} catch(e) {
  const start = claudeText.indexOf('{');
  const end = claudeText.lastIndexOf('}');
  if (start !== -1 && end !== -1) {
    try { parsed = JSON.parse(claudeText.substring(start, end + 1)); } catch(e2) {}
  }
}

const dateGen = $('Build Prompt Suggestions').first().json.dateGeneration;
const conseilGlobal = parsed.conseil_global || '';
const suggestions = parsed.suggestions || [];

return suggestions.map(s => ({
  json: {
    titre: s.titre || 'Post sans titre',
    plateforme: s.plateforme || 'Non defini',
    format: s.format || 'Non defini',
    hook: s.hook || '',
    messageCle: s.message_cle || '',
    cta: s.cta || '',
    hashtags: (s.hashtags || []).join(' '),
    priorite: s.priorite || 'Moyenne',
    problemeCible: s.probleme_cible || '',
    solution: s.solution || '',
    conseilGlobal,
    dateGeneration: dateGen
  }
}));

const items = $input.all();
const dateGen = items[0] ? items[0].json.dateGeneration : new Date().toISOString().split('T')[0];
const conseilGlobal = items[0] ? items[0].json.conseilGlobal : '';

const postsList = items.map((item, i) => {
  const j = item.json;
  return '<div style="border:1px solid #e0e0e0;border-radius:8px;padding:16px;margin:12px 0;">' +
    '<strong>[' + j.plateforme + ' — ' + j.format + ']</strong><br>' +
    '<strong style="color:#7c3aed">' + j.titre + '</strong> (' + j.priorite + ')<br><br>' +
    '<strong>Hook :</strong> ' + j.hook + '<br>' +
    '<strong>Message clé :</strong> ' + j.messageCle + '<br>' +
    '<strong>CTA :</strong> ' + j.cta + '<br>' +
    '<strong>Hashtags :</strong> ' + j.hashtags + '</div>';
}).join('');

const emailBody = '<h2 style="color:#7c3aed">💡 Suggestions de posts — ' + dateGen + '</h2>' +
  '<p><strong>Conseil stratégique global :</strong><br>' + conseilGlobal + '</p>' +
  '<h3>5 posts à produire cette semaine</h3>' +
  postsList +
  '<p style="color:#666;font-size:12px">Tous les posts ont été ajoutés au Backlog Notion ✅</p>';

return [{ json: { emailBody, dateGeneration: dateGen, nbSuggestions: items.length } }];
